let output;

// Extract the message from the Chat_Visio input and rename it as chatInput
if ($json.body && $json.body.message) {
  output = {
    chatInput: $json.body.message,  // Rename message to chatInput
  };
} else {
  output = {
    chatInput: "No chatInput found",  // Handle case where message is missing
  };
}

return output;

let output;

// Check if binary data (image) exists
if ($binary && $binary.data0) {
    return {
        route: "image_agent",
        reply: "Your image is being processed.",
        binary: $binary // Pass binary data to the next nodes
    };
}

try {
    // Try to parse the JSON from the Manager response or Action Agent
    output = JSON.parse($json.text || $json.reply);
} catch (error) {
    // If parsing fails, handle it as a regular text message
    return {
        route: "manager",  // Default route for handling non-JSON inputs
        reply: $json.text || $json.reply // Send the raw text as the reply
    };
}

// Check if the 'command' property exists, indicating an action agent response
if (output.command) {
    return {
        route: "action_agent",
        output: output,
    };
}

// Handle image route specifically
if (output.route === "image_agent") {
    return {
        route: "image_agent",
        reply: output.reply || "Image received and is being processed.",
        binary: $binary // Pass binary data to the next nodes
    };
}

// Return both the route and the reply for further processing if JSON parsing succeeds
return {
    route: output.route,   // Keep route for the Switch node
    reply: output.reply,   // Send reply to the Respond webhook
    binary: $binary // Pass binary data to the next nodes
};

// Extract the 'reply' field from the input JSON
let replyText = $json.reply;

// Ensure that we only return the reply text
return [
  {
    "text": replyText
  }
];

